INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(28001, 'Galatians 4:3', 'Galatians', 4, 3, '&nbsp;دغه شان چې مونږ هم کله نابالغه وُو نو مونږ هم د دُنياوى اصُولو غلامان وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28002, 'Galatians 4:4', 'Galatians', 4, 4, '&nbsp;خو کله چې وخت پوره شو نو خُدائ پاک خپل زوئ راولېږلو چې د ښځې نه پېدا شو او د شريعت د لاندې يې ژوند تېرولو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28003, 'Galatians 4:5', 'Galatians', 4, 5, '&nbsp;د دې دپاره چې هغه زمونږ فديه ورکړى او مونږ د شريعت نه آزاد کړى، نو چې په دې سره هغه مونږ د خپل زوئ په حيث قبول کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28004, 'Galatians 4:6', 'Galatians', 4, 6, '&nbsp;نو ځکه چې مونږ د خُدائ پاک بچى يُو نو خُدائ پاک د خپل زوئ روح زمونږ زړونو ته راولېږلو کوم روح چې په مونږ کښې دا آواز کوى چې، ”اے ابا، پلاره.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28005, 'Galatians 4:7', 'Galatians', 4, 7, '&nbsp;نو اوس نور تۀ غلام نۀ يې بلکې زوئ يې، او چې زوئ يې نو د خُدائ پاک وارث هم يې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28006, 'Galatians 4:8', 'Galatians', 4, 8, '&nbsp;پخوا چې تاسو خُدائ پاک نۀ پېژندو نو تاسو د هغه معبودانو غلامان وئ چې په حقيقت کښې خُدايان نۀ وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28007, 'Galatians 4:9', 'Galatians', 4, 9, '&nbsp;خو ولې اوس تاسو خُدائ پاک وپېژندلو، بلکې اوس خُدائ پاک تاسو وپېژندلئ، نو بيا تاسو خپلو هغه کمزورو او بې‌فائدې اولنو دُنياوى اصُولو ته ولې راګرځئ؟ او ولې ځان بيا د هغوئ غلام جوړول غواړئ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28008, 'Galatians 4:10', 'Galatians', 4, 10, '&nbsp;تاسو په ډېر غور سره خاص ورځې، مياشتې او مقرر موسمونه او کالونه مناووئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28009, 'Galatians 4:11', 'Galatians', 4, 11, '&nbsp;زۀ ستاسو په حقله دا يره محسوسوم هسې نه چې کومه خوارى چې ما په تاسو کړې ده هغه عبث لاړه شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28010, 'Galatians 4:12', 'Galatians', 4, 12, '&nbsp;زما وروڼو او خوېندو، زۀ تاسو ته منت کوم چې خپل ځانونه زما په شان د شريعت نه آزاد کړئ ځکه چې زۀ هم ستاسو په شان جوړ شوے يم. تاسو ما سره کوم خراب سلوک نۀ دے کړے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28011, 'Galatians 4:13', 'Galatians', 4, 13, '&nbsp;تاسو ته به ياد وى کوم زيرے چې ما تاسو ته اول اورولے وو په هغه وخت کښې زۀ بيمار وم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28012, 'Galatians 4:14', 'Galatians', 4, 14, '&nbsp;اګر کۀ زما بيمارۍ تاسو په آزمېښت کښې واچولئ، نۀ خو تاسو زۀ سپک وګڼلم او نۀ مو رانه کرکه وکړه، بلکې زما هرکلے مو لکه د خُدائ پاک د فرښتې او لکه د عيسىٰ مسيح په شان وکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28013, 'Galatians 4:15', 'Galatians', 4, 15, '&nbsp;زۀ د دې خبرې ګواهى ورکوم چې په هغه وخت کښې تاسو ما ته دومره خوشحاله وئ کۀ چرې دا ممکنه وه نو تاسو به د خوشحالۍ نه خپلې سترګې راويستې وې او ما له به مو راکړې وې خو اوس ستاسو هغه خوشحالى څۀ شوه؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28014, 'Galatians 4:16', 'Galatians', 4, 16, '&nbsp;نو ولې زۀ تاسو ته د حق وئيلو په وجه اوس ستاسو دشمن شوم؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28015, 'Galatians 4:17', 'Galatians', 4, 17, '&nbsp;هغوئ تاسو سره دوستانه کول غواړى خو د نېک مقصد دپاره نه، بلکې هغوئ دا غواړى چې تاسو زما نه جدا کړى د دې دپاره چې تاسو د هغوئ د دوستانې محتاجه شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28016, 'Galatians 4:18', 'Galatians', 4, 18, '&nbsp;دا ښۀ خبره ده چې په نېک کار کښې هر وخت د دوست جوړولو کوشش وکړے شى، نۀ صرف هغه وخت چې کله زۀ تاسو سره موجود يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28017, 'Galatians 4:19', 'Galatians', 4, 19, '&nbsp;زما ګرانو بچو، زۀ بيا ستاسو دپاره لکه د ماشوم د پېدا کېدو په درد آخته يم، ترڅو چې تاسو د مسيح په شان شوى نۀ يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28018, 'Galatians 4:20', 'Galatians', 4, 20, '&nbsp;زما دا خواهش دے چې زۀ اوس تاسو سره موجود وے، او خپل د خبرو انداز مې بدل کړے وے ځکه چې زۀ ستاسو په حقله پرېشانه يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28019, 'Galatians 4:21', 'Galatians', 4, 21, '&nbsp;تاسو څوک چې د شريعت تابعدارى کول غواړئ، ما ته دا ووايئ چې ولې تاسو په هغه خبره نۀ پوهېږئ څۀ چې شريعت وائى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28020, 'Galatians 4:22', 'Galatians', 4, 22, '&nbsp;نو دا ليکلے شوى دى چې د اِبراهيم دوه زامن وُو، يو د وينځې نه او بل د آزادې ښځې نه وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28021, 'Galatians 4:23', 'Galatians', 4, 23, '&nbsp;د وينځې زوئ په عام طور پېدا شو، او د آزادې ښځې زوئ د خُدائ پاک د وعدې په مطابق پېدا شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28022, 'Galatians 4:24', 'Galatians', 4, 24, '&nbsp;کۀ چرې مونږ په دې مثال پوهه شُو، دا دواړه ښځې د خُدائ پاک هغه دوه لوظونه ښکاره کوى. اوله ښځه چې هاجِره نوميږى چې هغه د سينا د غرۀ په مثال ده چرته چې خلقو ته شريعت مِلاو شو او هغه يې غلامان کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28023, 'Galatians 4:25', 'Galatians', 4, 25, '&nbsp;هاجِره په عربو کښې د سينا د غرۀ په مثال ده او څوک چې د موجوده يروشلم ښار په شان ده، ځکه چې د خپلو اولادونو سره په غلامۍ کښې ژوند کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28024, 'Galatians 4:26', 'Galatians', 4, 26, '&nbsp;خو هغه بله ښځه ساره د آسمانى يروشلم په شان ده، هغه آزاده ښځه ده، او هغه زمونږ مور ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28025, 'Galatians 4:27', 'Galatians', 4, 27, '&nbsp;ځکه چې په صحيفو کښې دا ليکلى دى چې، ”اے شنډې ښځې، خوشحالى وکړه، تا چې کله هم بچى نۀ دى راوړى او تا چې د ماشوم د راوړو درد نۀ دے تير کړے. نو تۀ د خوشحالۍ نه چغې ووهه، ځکه چې شنډه ښځه به د هغې ښځې نه زيات بچى راوړى څوک چې وادۀ شوې وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28026, 'Galatians 4:28', 'Galatians', 4, 28, '&nbsp;نو ملګرو، اوس تاسو د اِسحاق په شان د خُدائ پاک د وعدې بچى يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28027, 'Galatians 4:29', 'Galatians', 4, 29, '&nbsp;خو څنګه چې په هغه ورځو کښې په عام طور پېدا شوى زوئ د خُدائ پاک د روح په قدرت سره پېدا شوى زوئ وزورولو، نو هم هغه شان خبره اوس هم ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28028, 'Galatians 4:30', 'Galatians', 4, 30, '&nbsp;خو صحيفې څۀ وائى چې، ”وينځه او د هغې زوئ وشړئ ځکه چې د وينځې زوئ به د آزادې ښځې د زوئ په ميراث کښې شريک نۀ وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28029, 'Galatians 4:31', 'Galatians', 4, 31, '&nbsp;نو په دې وجه زما وروڼو او خوېندو، مونږ او تاسو اوس د وينځې بچى نۀ يُو، بلکې د آزادې ښځې بچى يُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28030, 'Galatians 5:1', 'Galatians', 5, 1, '&nbsp;مسيح مونږ د آزاد اوسېدلو دپاره آزاد کړى يُو. نو بيا په دې آزادۍ کښې قائم پاتې شئ، او په خپله غاړه د غلامۍ جغ بيا مۀ ږدئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28031, 'Galatians 5:2', 'Galatians', 5, 2, '&nbsp;ما ته غوږ شئ، زۀ پولوس تاسو ته دا وايم، کۀ چرې تاسو خپل ځان ته سنت د خلاصون ذريعه ګڼئ نو بيا تاسو ته د مسيح هيڅ فائده نشته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28032, 'Galatians 5:3', 'Galatians', 5, 3, '&nbsp;زۀ به يو ځل بيا هر يو کس ته دا په تاکيد سره ووايم، کۀ څوک خپل ځان سنت کړى نو هغه به بيا ضرور د شريعت په ټولو حکمونو پوره عمل کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28033, 'Galatians 5:4', 'Galatians', 5, 4, '&nbsp;ځکه کۀ تاسو په شريعت د عمل کولو په وسيله خپل ځان صادق کول غواړئ، نو په دې تاسو د مسيح سره خپل تعلق ختم کړو او د خُدائ پاک د فضل نه محروم پاتې شوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28034, 'Galatians 5:5', 'Galatians', 5, 5, '&nbsp;خو مونږ څوک چې په روحُ القُدس کښې ژوند کوُو، په ايمان سره د هغه صداقت، کوم چې خُدائ پاک راسره وعده کړې ده، ډېر په اُميد سره انتظار کوُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28035, 'Galatians 5:6', 'Galatians', 5, 6, '&nbsp;ځکه کۀ زمونږ ايمان په عيسىٰ مسيح وى، نو بيا سنت او ناسنت څۀ غټه خبره نۀ ده. خو کوم کار چې ضرورى دے، هغه صرف ايمان دے چې ځان په مينې سره څرګندوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28036, 'Galatians 5:7', 'Galatians', 5, 7, '&nbsp;تاسو خو ښۀ منډه وهله، نو بيا تاسو چا د حق د تابعدارۍ نه منع کړئ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28037, 'Galatians 5:8', 'Galatians', 5, 8, '&nbsp;دا رنګ لمسون د خُدائ پاک د طرف نه نۀ دے، چا چې تاسو آزادۍ ته رابللى يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28038, 'Galatians 5:9', 'Galatians', 5, 9, '&nbsp;نو دا ياد ساتئ چې لږه خمبيره ټول اخښلى اوړۀ خمبيره کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28039, 'Galatians 5:10', 'Galatians', 5, 10, '&nbsp;زما په تاسو په مالِک کښې دا پوره باور دے چې تاسو به بل غلط تعليم نۀ منئ. خو خُدائ پاک به داسې کس ته سزا ورکړى، څوک چې تاسو ګمراه کوى، کۀ هغه هر څوک هم وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28040, 'Galatians 5:11', 'Galatians', 5, 11, '&nbsp;خو زما وروڼو او خوېندو، ترڅو چې زما خبره ده کۀ زۀ تر اوسه د سنتېدلو پېغام ورکوم چې داسې کول ضرورى دى، نو بيا زۀ ولې تر اوسه زورَولے کېږم؟ کۀ ما د مسيح د سولۍ په وسيله د خلاصون تعليم نۀ وے ورکړے، نو څوک به هم خفه شوى نۀ وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28041, 'Galatians 5:12', 'Galatians', 5, 12, '&nbsp;زۀ غواړم چې هغه څوک چې تاسو د سنتولو په تعليم پرېشانه کوى هغوئ دې نۀ يواځې دا چې خپل ځانونه سنت کړى بلکې خصيان دې هم کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28042, 'Galatians 5:13', 'Galatians', 5, 13, '&nbsp;زما وروڼو او خوېندو، تاسو د آزادۍ دپاره رابللى شوى يئ. خو دا آزادى د ګناه د فطرت دپاره مۀ استعمالوئ، بلکې د زړۀ نه د يو بل خِدمت کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28043, 'Galatians 5:14', 'Galatians', 5, 14, '&nbsp;ځکه چې د ټول شريعت خلاصه صرف په دې يو حُکم کښې ده چې، ”تاسو د خپل ګاونډى سره د خپل ځان په شان مينه ساتئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28044, 'Galatians 5:15', 'Galatians', 5, 15, '&nbsp;خو کۀ چرې تاسو د يو بل وينې څښئ او جنګونه کوئ نو خبردار شئ چې په داسې کولو به يو بل برباد کړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28045, 'Galatians 5:16', 'Galatians', 5, 16, '&nbsp;نو زۀ دا وايم کۀ تاسو خپل ژوند د روحُ القُدس په مطابق تېروئ نو بيا به د ګناه فطرت په خپله پرېږدئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28046, 'Galatians 5:17', 'Galatians', 5, 17, '&nbsp;ځکه څۀ چې زمونږ د ګناه فطرت غواړى هغه د خُدائ پاک د روح خلاف دے، او څۀ چې د خُدائ پاک روح غواړى هغه د ګناه د فطرت خلاف دے، نو دا په خپلو کښې د يو بل خلاف دى، نو په دې وجه تاسو چې څۀ کول غواړئ هغه نۀ شئ کولے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28047, 'Galatians 5:18', 'Galatians', 5, 18, '&nbsp;خو کۀ چرې تاسو د خُدائ پاک د روح په هدايت روان يئ نو تاسو د شريعت پابند نۀ يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28048, 'Galatians 5:19', 'Galatians', 5, 19, '&nbsp;نو د ګناه د فطرت کارونه خو ښکاره دى، يعنې زنا، ناپاکى، عياشى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28049, 'Galatians 5:20', 'Galatians', 5, 20, '&nbsp;بُت پرستى، جادوګرى، دشمنى، جګړې، کينه، بار بار غصه، خود غرضى، فتنې، پارټى بازى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28050, 'Galatians 5:21', 'Galatians', 5, 21, '&nbsp;بُغض، نشې، مستى او د دې په شان نور ګناهونه. زۀ تاسو ته بيا خبردارے درکوم لکه څنګه چې ما تاسو ته وړاندې درکړے وو، هغه څوک چې داسې کارونه کوى نو هغوئ به د خُدائ پاک د بادشاهۍ وارثان نۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28051, 'Galatians 5:22', 'Galatians', 5, 22, '&nbsp;خو د خُدائ پاک د روح مېوه مينه، خوشحالى، سکون، صبر، مهربانى، ښېګړه، وفادارى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28052, 'Galatians 5:23', 'Galatians', 5, 23, '&nbsp;نرمى او پرهيزګارى ده. يو شريعت هم د داسې کارونو خلاف نۀ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28053, 'Galatians 5:24', 'Galatians', 5, 24, '&nbsp;او څوک چې د عيسىٰ مسيح دى نو هغوئ د خپل د ګناه د فطرت ټول شوقونه او خواهشونه په سولۍ کړى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
