(28090, 'Ephesians 1:17', 'Ephesians', 1, 17, '&nbsp;زۀ دُعا کوم چې زمونږ د مالِک عيسىٰ مسيح جلالى پلار خُدائ پاک دې تاسو ته د حکمت او پېژندګلو روح درکړى ترڅو چې تاسو د هغۀ په پېژندلو کښې ترقى وکړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28091, 'Ephesians 1:18', 'Ephesians', 1, 18, '&nbsp;نو زۀ دُعا کوم چې ستاسو د زړۀ سترګې دې روښانه شى چې تاسو په دې پوهه شئ چې هغۀ تاسو د څومره لوئ اُميد دپاره رابللى يئ، يعنې هغه شاندار ميراث له چې هغۀ د خپلو مقدسينو دپاره ساتلے دے څومره لوئ دولت دے،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
