(28093, 'Ephesians 1:20', 'Ephesians', 1, 20, '&nbsp;دا هم هغه قوت دے چې د کوم په وسيله چې خُدائ پاک مسيح د مړو نه بيا راژوندے کړو او خپل ښى لاس ته يې په آسمان کښې کښېنولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28094, 'Ephesians 1:21', 'Ephesians', 1, 21, '&nbsp;هلته يې مسيح د هر قسم حکومت او اختيار او قدرت او رياست او د هر يو نوم نه زيات اوچت کړو کوم چې به نۀ تش په دې دُنيا کښې بلکې په راتلونکې دُنيا کښې هم اوچت وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28095, 'Ephesians 1:22', 'Ephesians', 1, 22, '&nbsp;او خُدائ پاک هر څۀ د مسيح د پښو لاندې کړل او هغه يې د جماعت په ټولو څيزونو سردار جوړ کړو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28096, 'Ephesians 1:23', 'Ephesians', 1, 23, '&nbsp;او جماعت د مسيح بدن دے. او د مسيح نه پوره معمورتيا حاصلوى او هم دې وخت کښې ټول کائنات د خپل حضور نه ډکوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28097, 'Ephesians 2:1', 'Ephesians', 2, 1, '&nbsp;تاسو هم د خپلو نافرمانو او ګناهونو په وجه مړۀ وئ،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28098, 'Ephesians 2:2', 'Ephesians', 2, 2, '&nbsp;ځکه چې تاسو هم پخوا د دې دُنيا په کږو لارو روان وئ، او د پيريانو د سردار، يعنې هغه روح پسې تلئ کوم چې اوس په نافرمانو بچو کښې کار کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28099, 'Ephesians 2:3', 'Ephesians', 2, 3, '&nbsp;يو وخت مونږ هم دغه شان د خپل وجود د خواهشونو په مطابق ژوند تېرولو او د ګناه د فطرت مرضى مو پوره کوله، او مونږ هم لکه د نورو په شان په فطرى توګه د خُدائ پاک د غضب د لاندې وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28100, 'Ephesians 2:4', 'Ephesians', 2, 4, '&nbsp;خو خُدائ پاک چې په رحم غنى دے هغۀ د خپلې لوئې مينې په وجه مونږ سره ډېره مينه وکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');